		t.Fatal(err)
	}

	want := map[string]models.Confidence{
		"CVE-2021-0001": models.CpeVendorProductMatch, // JVN only
		"CVE-2021-0002": models.CpeVersionMatch,       // NVD only
		"CVE-2021-0003": models.CpeVersionMatch,       // both -> NVD wins
	}
	for cveID, w := range want {
		v, ok := r.ScannedCves[cveID]
		if !ok {
			t.Fatalf("%s not found in scanned cves", cveID)
		}
		if len(v.Confidences) != 1 {
			t.Fatalf("%s: unexpected confidences %+v", cveID, v.Confidences)
		}
		if v.Confidences[0] != w {
			t.Fatalf("%s: got %+v want %+v", cveID, v.Confidences[0], w)
		}
		if len(v.CpeURIs) != 1 || v.CpeURIs[0] != "cpe:/a:hitachi_abb_power_grids:afs660" {
			t.Fatalf("%s: unexpected cpe uris %+v", cveID, v.CpeURIs)
		}
	}
}
